/*Table structure for table `emailaddress` */

CREATE TABLE `emailaddress` (
  `EmailAddressNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `SMTPserver` varchar(255) NOT NULL,
  `EmailUsername` varchar(255) NOT NULL,
  `EmailPassword` varchar(255) NOT NULL,
  `ServerPort` int(11) NOT NULL,
  `UseSSL` tinyint(4) NOT NULL,
  `SenderAddress` varchar(255) NOT NULL,
  `Pop3ServerIncoming` varchar(255) NOT NULL,
  `ServerPortIncoming` int(11) NOT NULL,
  `UserNum` bigint(20) NOT NULL,
  `AccessToken` varchar(2000) NOT NULL,
  `RefreshToken` text NOT NULL,
  `DownloadInbox` tinyint(4) NOT NULL,
  `QueryString` varchar(1000) NOT NULL,
  `AuthenticationType` tinyint(4) NOT NULL,
  PRIMARY KEY (`EmailAddressNum`),
  KEY `UserNum` (`UserNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `emailattach` */

CREATE TABLE `emailattach` (
  `EmailAttachNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `EmailMessageNum` bigint(20) NOT NULL,
  `DisplayedFileName` varchar(255) DEFAULT '',
  `ActualFileName` varchar(255) DEFAULT '',
  `EmailTemplateNum` bigint(20) NOT NULL,
  PRIMARY KEY (`EmailAttachNum`),
  KEY `EmailMessageNum` (`EmailMessageNum`),
  KEY `EmailTemplateNum` (`EmailTemplateNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `emailautograph` */

CREATE TABLE `emailautograph` (
  `EmailAutographNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `Description` text NOT NULL,
  `EmailAddress` varchar(255) NOT NULL,
  `AutographText` text NOT NULL,
  PRIMARY KEY (`EmailAutographNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `emailhostingtemplate` */

CREATE TABLE `emailhostingtemplate` (
  `EmailHostingTemplateNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `TemplateName` varchar(255) NOT NULL,
  `Subject` text NOT NULL,
  `BodyPlainText` mediumtext NOT NULL,
  `BodyHTML` mediumtext NOT NULL,
  `TemplateId` bigint(20) NOT NULL,
  `ClinicNum` bigint(20) NOT NULL,
  `EmailTemplateType` varchar(255) NOT NULL,
  `TemplateType` varchar(255) NOT NULL,
  PRIMARY KEY (`EmailHostingTemplateNum`),
