/*Table structure for table `feeschedgroup` */

CREATE TABLE `feeschedgroup` (
  `FeeSchedGroupNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `Description` varchar(255) NOT NULL,
  `FeeSchedNum` bigint(20) NOT NULL,
  `ClinicNums` varchar(255) NOT NULL,
  PRIMARY KEY (`FeeSchedGroupNum`),
  KEY `FeeSchedNum` (`FeeSchedNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `feeschednote` */

CREATE TABLE `feeschednote` (
  `FeeSchedNoteNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `FeeSchedNum` bigint(20) NOT NULL,
  `ClinicNums` text NOT NULL,
  `Note` text NOT NULL,
  `DateEntry` date NOT NULL DEFAULT '0001-01-01',
  `SecUserNumEntry` bigint(20) NOT NULL,
  `SecDateEntry` date NOT NULL DEFAULT '0001-01-01',
  `SecDateTEdit` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`FeeSchedNoteNum`),
  KEY `FeeSchedNum` (`FeeSchedNum`),
  KEY `SecUserNumEntry` (`SecUserNumEntry`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `fhircontactpoint` */

CREATE TABLE `fhircontactpoint` (
  `FHIRContactPointNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `FHIRSubscriptionNum` bigint(20) NOT NULL,
  `ContactSystem` tinyint(4) NOT NULL,
  `ContactValue` varchar(255) NOT NULL,
  `ContactUse` tinyint(4) NOT NULL,
  `ItemOrder` int(11) NOT NULL,
  `DateStart` date NOT NULL DEFAULT '0001-01-01',
  `DateEnd` date NOT NULL DEFAULT '0001-01-01',
  PRIMARY KEY (`FHIRContactPointNum`),
  KEY `FHIRSubscriptionNum` (`FHIRSubscriptionNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `fhirsubscription` */

CREATE TABLE `fhirsubscription` (
  `FHIRSubscriptionNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `Criteria` varchar(255) NOT NULL,
  `Reason` varchar(255) NOT NULL,
  `SubStatus` tinyint(4) NOT NULL,
  `ErrorNote` text NOT NULL,
  `ChannelType` tinyint(4) NOT NULL,
  `ChannelEndpoint` varchar(255) NOT NULL,
  `ChannelPayLoad` varchar(255) NOT NULL,
  `ChannelHeader` varchar(255) NOT NULL,
  `DateEnd` datetime NOT NULL DEFAULT '0001-01-01 00:00:00',
  `APIKeyHash` varchar(255) NOT NULL,
  PRIMARY KEY (`FHIRSubscriptionNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `fielddeflink` */

CREATE TABLE `fielddeflink` (
  `FieldDefLinkNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `FieldDefNum` bigint(20) NOT NULL,
  `FieldDefType` tinyint(4) NOT NULL,
  `FieldLocation` tinyint(4) NOT NULL,
  PRIMARY KEY (`FieldDefLinkNum`),
  KEY `FieldDefNum` (`FieldDefNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `files` */

CREATE TABLE `files` (
  `DocNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `Data` longblob NOT NULL,
  `Thumbnail` longblob DEFAULT NULL,
  PRIMARY KEY (`DocNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `formpat` */

CREATE TABLE `formpat` (
  `FormPatNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `PatNum` bigint(20) NOT NULL,
  `FormDateTime` datetime NOT NULL DEFAULT '0001-01-01 00:00:00',
  PRIMARY KEY (`FormPatNum`),
  KEY `PatNum` (`PatNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `glidewellacct` */

CREATE TABLE `glidewellacct` (
  `GlidewellAcctNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `AccountNumber` varchar(255) NOT NULL,
  `ApiKey` varchar(255) NOT NULL,
  `DateTimeExpires` datetime NOT NULL DEFAULT '0001-01-01 00:00:00',
  PRIMARY KEY (`GlidewellAcctNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `glidewellmsg` */

CREATE TABLE `glidewellmsg` (
  `GlidewellMsgNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `LabCaseNum` bigint(20) NOT NULL,
  `OrderStatus` tinyint(4) NOT NULL,
  `VendorRxId` varchar(255) NOT NULL,
  `PatNum` bigint(20) NOT NULL,
  `GlidewellAcctNum` bigint(20) NOT NULL,
  `RawJsonResponse` text NOT NULL,
  `RawJsonRequest` text NOT NULL,
  `SentITero` tinyint(4) NOT NULL,
  `SentMedit` tinyint(4) NOT NULL,
  PRIMARY KEY (`GlidewellMsgNum`),
  KEY `LabCaseNum` (`LabCaseNum`),
  KEY `PatNum` (`PatNum`),
  KEY `GlidewellAcctNum` (`GlidewellAcctNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `gradingscale` */

CREATE TABLE `gradingscale` (
  `GradingScaleNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `Description` varchar(255) NOT NULL,
  `ScaleType` tinyint(4) NOT NULL,
  PRIMARY KEY (`GradingScaleNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `gradingscaleitem` */

CREATE TABLE `gradingscaleitem` (
  `GradingScaleItemNum` bigint(20) NOT NULL AUTO_INCREMENT,
