/*Table structure for table `procedurelog` */

CREATE TABLE `procedurelog` (
  `ProcNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `PatNum` bigint(20) NOT NULL,
  `AptNum` bigint(20) NOT NULL,
  `OldCode` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '',
  `ProcDate` date NOT NULL DEFAULT '0001-01-01',
  `ProcFee` double NOT NULL DEFAULT 0,
  `Surf` varchar(10) DEFAULT '',
  `ToothNum` varchar(2) DEFAULT '',
  `ToothRange` varchar(100) DEFAULT '',
  `Priority` bigint(20) NOT NULL,
  `ProcStatus` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `ProvNum` bigint(20) NOT NULL,
  `Dx` bigint(20) NOT NULL,
  `PlannedAptNum` bigint(20) NOT NULL,
  `PlaceService` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `Prosthesis` char(1) DEFAULT '',
  `DateOriginalProsth` date NOT NULL DEFAULT '0001-01-01',
  `ClaimNote` varchar(80) DEFAULT '',
  `DateEntryC` date NOT NULL DEFAULT '0001-01-01',
  `ClinicNum` bigint(20) NOT NULL,
  `MedicalCode` varchar(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '',
  `DiagnosticCode` varchar(255) DEFAULT '',
  `IsPrincDiag` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `ProcNumLab` bigint(20) NOT NULL,
  `BillingTypeOne` bigint(20) NOT NULL,
  `BillingTypeTwo` bigint(20) NOT NULL,
  `CodeNum` bigint(20) NOT NULL,
  `CodeMod1` char(2) DEFAULT NULL,
  `CodeMod2` char(2) DEFAULT NULL,
  `CodeMod3` char(2) DEFAULT NULL,
  `CodeMod4` char(2) DEFAULT NULL,
  `RevCode` varchar(45) DEFAULT NULL,
  `UnitQty` int(11) NOT NULL,
  `BaseUnits` int(11) NOT NULL,
  `StartTime` int(11) NOT NULL,
  `StopTime` int(11) NOT NULL,
  `DateTP` date NOT NULL DEFAULT '0001-01-01',
  `SiteNum` bigint(20) NOT NULL,
  `HideGraphics` tinyint(4) NOT NULL,
  `CanadianTypeCodes` varchar(20) NOT NULL,
  `ProcTime` time NOT NULL,
  `ProcTimeEnd` time NOT NULL,
  `DateTStamp` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `Prognosis` bigint(20) NOT NULL,
  `DrugUnit` tinyint(4) NOT NULL,
  `DrugQty` float NOT NULL,
  `UnitQtyType` tinyint(4) NOT NULL,
  `StatementNum` bigint(20) NOT NULL,
  `IsLocked` tinyint(4) NOT NULL,
  `BillingNote` varchar(255) NOT NULL,
  `RepeatChargeNum` bigint(20) NOT NULL,
  `SnomedBodySite` varchar(255) NOT NULL,
  `DiagnosticCode2` varchar(255) NOT NULL,
  `DiagnosticCode3` varchar(255) NOT NULL,
  `DiagnosticCode4` varchar(255) NOT NULL,
  `ProvOrderOverride` bigint(20) NOT NULL,
  `Discount` double NOT NULL,
  `IsDateProsthEst` tinyint(4) NOT NULL,
  `IcdVersion` tinyint(3) unsigned NOT NULL,
  `IsCpoe` tinyint(4) NOT NULL,
  `SecUserNumEntry` bigint(20) NOT NULL,
  `SecDateEntry` datetime NOT NULL DEFAULT '0001-01-01 00:00:00',
  `DateComplete` date NOT NULL DEFAULT '0001-01-01',
  `OrderingReferralNum` bigint(20) NOT NULL,
  `TaxAmt` double NOT NULL,
  `Urgency` tinyint(4) NOT NULL,
  `DiscountPlanAmt` double NOT NULL,
  `NoBillIns` tinyint(4) NOT NULL,
  PRIMARY KEY (`ProcNum`),
  KEY `CodeNum` (`CodeNum`),
  KEY `PlannedAptNum` (`PlannedAptNum`),
  KEY `BillingTypeOne` (`BillingTypeOne`),
  KEY `BillingTypeTwo` (`BillingTypeTwo`),
  KEY `Prognosis` (`Prognosis`),
  KEY `procedurelog_ProcNumLab` (`ProcNumLab`),
  KEY `StatementNum` (`StatementNum`),
  KEY `RepeatChargeNum` (`RepeatChargeNum`),
  KEY `ProvOrderOverride` (`ProvOrderOverride`),
  KEY `indexPNPSCN` (`PatNum`,`ProcStatus`,`ClinicNum`),
  KEY `indexPNPD` (`ProvNum`,`ProcDate`),
  KEY `SecUserNumEntry` (`SecUserNumEntry`),
  KEY `ClinicNum` (`ClinicNum`),
  KEY `indexAgingCovering` (`PatNum`,`ProcStatus`,`ProcFee`,`UnitQty`,`BaseUnits`,`ProcDate`),
  KEY `OrderingReferralNum` (`OrderingReferralNum`),
  KEY `PatStatusCodeDate` (`PatNum`,`ProcStatus`,`CodeNum`,`ProcDate`),
  KEY `DateComplete` (`DateComplete`),
  KEY `RadiologyProcs` (`AptNum`,`CodeNum`,`ProcStatus`,`IsCpoe`,`ProvNum`),
  KEY `Priority` (`Priority`),
  KEY `DateClinicStatus` (`ProcDate`,`ClinicNum`,`ProcStatus`),
  KEY `DateTStampPN` (`DateTStamp`,`PatNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `procgroupitem` */

CREATE TABLE `procgroupitem` (
  `ProcGroupItemNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `ProcNum` bigint(20) NOT NULL,
  `GroupNum` bigint(20) NOT NULL,
  PRIMARY KEY (`ProcGroupItemNum`),
  KEY `ProcNum` (`ProcNum`),
  KEY `GroupNum` (`GroupNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `procmultivisit` */

CREATE TABLE `procmultivisit` (
  `ProcMultiVisitNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `GroupProcMultiVisitNum` bigint(20) NOT NULL,
  `ProcNum` bigint(20) NOT NULL,
  `ProcStatus` tinyint(4) NOT NULL,
  `IsInProcess` tinyint(4) NOT NULL,
  `SecDateTEntry` datetime NOT NULL DEFAULT '0001-01-01 00:00:00',
  `SecDateTEdit` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `PatNum` bigint(20) NOT NULL,
  PRIMARY KEY (`ProcMultiVisitNum`),
  KEY `GroupProcMultiVisitNum` (`GroupProcMultiVisitNum`),
  KEY `ProcNum` (`ProcNum`),
  KEY `IsInProcess` (`IsInProcess`),
  KEY `SecDateTEntry` (`SecDateTEntry`),
  KEY `SecDateTEdit` (`SecDateTEdit`),
  KEY `PatNum` (`PatNum`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `procnote` */

CREATE TABLE `procnote` (
  `ProcNoteNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `PatNum` bigint(20) NOT NULL,
  `ProcNum` bigint(20) NOT NULL,
  `EntryDateTime` datetime NOT NULL DEFAULT '0001-01-01 00:00:00',
  `UserNum` bigint(20) NOT NULL,
  `Note` text DEFAULT NULL,
  `SigIsTopaz` tinyint(3) unsigned NOT NULL,
  `Signature` text DEFAULT NULL,
  `UserNum2` bigint(20) NOT NULL,
  `Signature2` text DEFAULT NULL,
  `SigIsTopaz2` tinyint(3) unsigned NOT NULL,
  PRIMARY KEY (`ProcNoteNum`),
  KEY `PatNum` (`PatNum`),
  KEY `ProcNum` (`ProcNum`),
  KEY `UserNum` (`UserNum`),
  KEY `UserNum2` (`UserNum2`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `proctp` */

CREATE TABLE `proctp` (
  `ProcTPNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `TreatPlanNum` bigint(20) NOT NULL,
  `PatNum` bigint(20) NOT NULL,
  `ProcNumOrig` bigint(20) NOT NULL,
  `ItemOrder` smallint(5) unsigned NOT NULL DEFAULT 0,
  `Priority` bigint(20) NOT NULL,
  `ToothNumTP` varchar(255) DEFAULT '',
  `Surf` varchar(255) DEFAULT '',
  `ProcCode` varchar(15) DEFAULT NULL,
  `Descript` varchar(255) DEFAULT '',
  `FeeAmt` double NOT NULL DEFAULT 0,
  `PriInsAmt` double NOT NULL DEFAULT 0,
  `SecInsAmt` double NOT NULL DEFAULT 0,
  `PatAmt` double NOT NULL DEFAULT 0,
  `Discount` double NOT NULL,
  `Prognosis` varchar(255) NOT NULL,
  `Dx` varchar(255) NOT NULL,
  `ProcAbbr` varchar(50) NOT NULL,
  `SecUserNumEntry` bigint(20) NOT NULL,
  `SecDateEntry` date NOT NULL DEFAULT '0001-01-01',
  `SecDateTEdit` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `FeeAllowed` double NOT NULL,
  `TaxAmt` double NOT NULL,
  `ProvNum` bigint(20) NOT NULL,
  `DateTP` date NOT NULL DEFAULT '0001-01-01',
  `ClinicNum` bigint(20) NOT NULL,
  `CatPercUCR` double NOT NULL,
  PRIMARY KEY (`ProcTPNum`),
  KEY `indexPatNum` (`PatNum`),
  KEY `indexTreatPlanNum` (`TreatPlanNum`),
  KEY `SecUserNumEntry` (`SecUserNumEntry`),
  KEY `ProvNum` (`ProvNum`),
  KEY `ClinicNum` (`ClinicNum`),
  KEY `ProcNumOrig` (`ProcNumOrig`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

/*Table structure for table `program` */

CREATE TABLE `program` (
  `ProgramNum` bigint(20) NOT NULL AUTO_INCREMENT,
  `ProgName` varchar(100) DEFAULT '',
  `ProgDesc` varchar(100) DEFAULT '',
  `Enabled` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `Path` text NOT NULL DEFAULT '',
  `CommandLine` text NOT NULL DEFAULT '',
  `Note` text DEFAULT NULL,
  `PluginDllName` varchar(255) NOT NULL,
  `ButtonImage` text NOT NULL,
  `FileTemplate` text NOT NULL,
